WRITES = json.loads('{"lib/account_cloud.dart": "", "test/account_cloud_storage_backend_test.dart": "", "release/SIGNED_BUILD_PIPELINE.md": "", "release/FIREBASE_CLOUD_SYNC.md": "", "reports/RC1_MANUAL_TEST_CHECKLIST.md": ""}')
EXPECTED_HASHES = json.loads('{"lib/account_cloud.dart": "9c503f8e024bf47c3348f1b720c18729c93e784e121892ca10ce9fcc37448804", "release/SIGNED_BUILD_PIPELINE.md": "c84964543097051595ed7a2ffb3b80e7c035cd8d7a4cca7ae81b0c28b3ad38e7", "release/FIREBASE_CLOUD_SYNC.md": "bff79c545028832d7f000b54d2f1a14e8c8d15749750ee671cbeaa4302b8a399", "reports/RC1_MANUAL_TEST_CHECKLIST.md": "34e9acb69c2d77697c5ccaf81cbd671eeea60cbfe7013ba4124a2258224e3c6e"}')

QUESTIONS = Path("assets/questions.json")
TARGETS = sorted(
    set(PATCHES) | set(WRITES)
)


class InstallError(RuntimeError):
    pass


def decode(value: str) -> str:
    return base64.b64decode(value).decode("utf-8")


def run(
    args: list[str],
    *,
    check: bool = True,
    timeout: int | None = None,
    env: dict[str, str] | None = None,
) -> subprocess.CompletedProcess[str]:
    result = subprocess.run(
        args,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=timeout,
        env=env,
    )
    if result.stdout:
        print(result.stdout, end="")
    if check and result.returncode != 0:
        raise InstallError(
            f"Komut başarısız: {' '.join(args)}"
        )
    return result


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def current_version() -> str:
    for line in Path("pubspec.yaml").read_text(
        encoding="utf-8"
    ).splitlines():
        if line.startswith("version:"):
            return line.split(":", 1)[1].strip()
    raise InstallError("pubspec.yaml sürümü bulunamadı.")


def head_file_text(path: str) -> str:
    result = run(
        ["git", "show", f"HEAD:{path}"],
        check=False,
    )
    if result.returncode != 0:
        raise InstallError(
            f"HEAD içinde dosya bulunamadı: {path}"
        )
    return result.stdout


def version_from_text(text: str) -> str:
    for line in text.splitlines():
        if line.startswith("version:"):
            return line.split(":", 1)[1].strip()
    raise InstallError(
        "HEAD pubspec.yaml sürümü bulunamadı."
    )


def repair_stale_pubspec_from_head() -> None:
    local_version = current_version()
    head_text = head_file_text("pubspec.yaml")
    head_version = version_from_text(head_text)

    if local_version == EXPECTED_VERSION:
        return

    if head_version != EXPECTED_VERSION:
        raise InstallError(
            "Git geçmişindeki taban sürüm de beklenmiyor. "
            f"HEAD: {head_version}, beklenen: {EXPECTED_VERSION}."
        )

    # Codespaces çalışma ağacında eski içerik kalmışsa yalnızca
    # pubspec.yaml dosyasını doğrulanmış HEAD sürümüne döndür.
    run(
        [
            "git",
            "update-index",
            "--no-assume-unchanged",
            "pubspec.yaml",
        ],
        check=False,
    )
    run(
        [
            "git",
            "update-index",
            "--no-skip-worktree",
            "pubspec.yaml",
        ],
        check=False,
    )
    run(
        [
            "git",
            "restore",
            "--source=HEAD",
            "--worktree",
            "--",
            "pubspec.yaml",
        ]
    )

    repaired_version = current_version()
    if repaired_version != EXPECTED_VERSION:
        raise InstallError(
            "pubspec.yaml HEAD sürümüne geri getirilemedi. "
            f"Mevcut: {repaired_version}."
        )

    print(
        "✓ Codespaces içinde eski kalan pubspec.yaml "
        "HEAD sürümünden onarıldı."
    )


def ensure_repo() -> None:
    if not Path(".git").exists():
        raise InstallError(
            "Bu dosya depo kökünde çalıştırılmalı."
        )

    branch = run(
        ["git", "branch", "--show-current"]
    ).stdout.strip()
    if branch != "main":
        raise InstallError(
            f"Beklenen dal main, mevcut dal: {branch}"
        )

    repair_stale_pubspec_from_head()

    if current_version() != EXPECTED_VERSION:
        raise InstallError(
            "Beklenen taban sürüm "
            f"{EXPECTED_VERSION}, mevcut sürüm "
            f"{current_version()}."
        )

    if not QUESTIONS.exists():
        raise InstallError(
            "assets/questions.json bulunamadı."
        )

    changed = run(
        [
            "git",
            "status",
            "--porcelain",
            "--",
            *TARGETS,
        ]
    ).stdout.strip()
    if changed:
        raise InstallError(
            "Hedef dosyalarda ilgisiz yerel değişiklik var:\n"
            + changed
        )


def verify_hashes() -> None:
    for raw_path, expected in EXPECTED_HASHES.items():
        path = Path(raw_path)
        if not path.exists():
            raise InstallError(
                f"Beklenen dosya bulunamadı: {path}"
            )
        actual = sha256(path)
        if actual != expected:
            raise InstallError(
                f"{path} beklenen sürümde değil. "
                "Dosya değiştirilmedi."
            )


def preflight() -> None:
    errors: list[str] = []

    for raw_path, items in PATCHES.items():
        path = Path(raw_path)
        if not path.exists():
            errors.append(f"Dosya yok: {path}")
            continue

        simulated = path.read_text(encoding="utf-8")
        for index, item in enumerate(items, start=1):
            old = decode(item["old"])
            new = decode(item["new"])
            expected = int(item["count"])
            actual = simulated.count(old)

            if actual != expected:
                preview = old.replace("\n", "\\n")[:150]
                errors.append(
                    f"{path} • yama {index}: "
                    f"{preview!r} eşleşmesi {actual}, "
                    f"beklenen {expected}"
                )
                break

            simulated = simulated.replace(old, new)

    new_test = Path(
        "test/account_cloud_storage_backend_test.dart"
    )
    if new_test.exists():
        errors.append(
            f"Yeni test zaten var: {new_test}"
        )

    if errors:
        raise InstallError(
            "Ön kontrol başarısız:\n- "
            + "\n- ".join(errors)
        )


def apply_changes() -> None:
    for raw_path, items in PATCHES.items():
        path = Path(raw_path)
        text = path.read_text(encoding="utf-8")

        for item in items:
            old = decode(item["old"])
            new = decode(item["new"])
            text = text.replace(old, new)

        path.write_text(text, encoding="utf-8")

    for raw_path, encoded in WRITES.items():
        path = Path(raw_path)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            decode(encoded),
            encoding="utf-8",
        )


def verify_result(question_hash: str) -> None:
    if current_version() != NEW_VERSION:
        raise InstallError(
            "Yeni sürüm pubspec.yaml içine yazılamadı."
        )

    if sha256(QUESTIONS) != question_hash:
        raise InstallError(
            "assets/questions.json değişti; işlem durduruldu."
        )

    account = Path("lib/account_cloud.dart").read_text(
        encoding="utf-8"
    )
    snapshot_start = account.index(
        "class AccountLocalSnapshot"
    )
    snapshot_end = account.index(
        "class AccountCloudService"
    )
    snapshot_block = account[
        snapshot_start:snapshot_end
    ]

    required = [
        "SharedPreferencesAsync _preferences",
        "await _preferences.getAll()",
        "await _preferences.getKeys()",
        "GetOptions(source: Source.server)",
        "snapshotValueCount",
        "Bulut kaydı sunucuda doğrulanamadı.",
    ]
    missing = [
        item for item in required
        if item not in account
    ]
    if missing:
        raise InstallError(
            "Hotfix doğrulaması eksik: "
            + ", ".join(missing)
        )

    if "SharedPreferences.getInstance()" in snapshot_block:
        raise InstallError(
            "Bulut snapshot sınıfında eski veri deposu kaldı."
        )

    if not Path(
        "test/account_cloud_storage_backend_test.dart"
    ).exists():
        raise InstallError(
            "Depolama regresyon testi oluşturulamadı."
        )


def run_checks() -> None:
    dart = shutil.which("dart")
    flutter = shutil.which("flutter")

    if dart:
        run(
            [
                dart,
                "format",
                "lib/account_cloud.dart",
                "lib/app_build_info.dart",
                "test/rc1_quality_gate_test.dart",
                "test/account_cloud_policy_test.dart",
                "test/account_cloud_storage_backend_test.dart",
            ]
        )
    else:
        print(
            "ℹ Dart bulunamadı; biçim kontrolü Actions'a bırakıldı."
        )

    if flutter:
        run([flutter, "pub", "get"])
        run(
            [
                flutter,
                "analyze",
                "--no-fatal-warnings",
                "--no-fatal-infos",
            ]
        )
        run([flutter, "test"])
    else:
        print(
            "ℹ Flutter bulunamadı; analiz ve testler Actions'a bırakıldı."
        )


def commit_and_push() -> None:
    intended = TARGETS

    run(["git", "add", "--", *intended])

    staged = run(
        ["git", "diff", "--cached", "--name-only"]
    ).stdout.splitlines()

    unexpected = sorted(set(staged) - set(intended))
    if unexpected:
        raise InstallError(
            "İstenmeyen dosyalar stage edildi: "
            + ", ".join(unexpected)
        )

    run(["git", "commit", "-m", COMMIT_MESSAGE])

    env = os.environ.copy()
    env.pop("GH_TOKEN", None)
    env.pop("GITHUB_TOKEN", None)
    env["GIT_TERMINAL_PROMPT"] = "0"

    try:
        result = run(
            ["git", "push", "origin", "main"],
            check=False,
            timeout=120,
            env=env,
        )
    except subprocess.TimeoutExpired:
        print(
            "\n⚠ Commit hazır ama push 120 saniyede "
            "tamamlanmadı."
        )
        print(
            "Yeni terminalde çalıştır:\n"
            "env -u GH_TOKEN -u GITHUB_TOKEN "
            "GIT_TERMINAL_PROMPT=0 git push origin main"
        )
        return

    if result.returncode != 0:
        print(
            "\n⚠ Commit hazır ama push tamamlanmadı."
        )
        print(
            "Yeni terminalde çalıştır:\n"
            "env -u GH_TOKEN -u GITHUB_TOKEN "
            "GIT_TERMINAL_PROMPT=0 git push origin main"
        )
        return

    print("✓ Commit GitHub'a gönderildi.")


def main() -> int:
    print(
        "Bilgi Rotası — Bulut Kayıt DataStore Hotfix V2"
    )
    print(
        "Hedef: 1.47.1+63 • RC2"
    )

    backup_dir: Path | None = None
    question_hash = ""

    try:
        ensure_repo()
        verify_hashes()
        preflight()
        print(
            "✓ Gerçek dosyalar ve tüm yamalar "
            "değişiklikten önce doğrulandı."
        )

        question_hash = sha256(QUESTIONS)
        backup_dir = Path(
            tempfile.mkdtemp(
                prefix="bilgi_rotasi_cloud_hotfix_"
            )
        )

        for raw_path in TARGETS:
            path = Path(raw_path)
            if not path.exists():
                continue
            destination = backup_dir / raw_path
            destination.parent.mkdir(
                parents=True,
                exist_ok=True,
            )
            shutil.copy2(path, destination)

        apply_changes()
        verify_result(question_hash)
        run_checks()
        verify_result(question_hash)
        commit_and_push()

        print()
        print("HOTFIX BAŞARILI")
        print("Sürüm   : 1.47.1+63 • RC2")
        print(
            "Artifact: "
            "BilgiRotasi-Signed-RC2-1.47.1-63"
        )
        print(
            "APK     : "
            "BilgiRotasi-1.47.1-63-signed.apk"
        )
        return 0

    except Exception as error:
        print()
        print("HOTFIX DURDURULDU")
        print(str(error))

        if backup_dir is not None:
            for raw_path in TARGETS:
                backup = backup_dir / raw_path
                target = Path(raw_path)

                if backup.exists():
                    target.parent.mkdir(
                        parents=True,
                        exist_ok=True,
                    )
                    shutil.copy2(backup, target)
                elif target.exists():
                    target.unlink()

            print(
                "✓ Hedef dosyalar yedekten geri alındı."
            )

        return 1

    finally:
        if backup_dir is not None:
            shutil.rmtree(
                backup_dir,
                ignore_errors=True,
            )


if __name__ == "__main__":
    raise SystemExit(main())
